import {
  ProjectEntity,
  ProjectStatus,
  ChangelogEntityType,
} from "./domain";
import { IndexedDbService } from "./indexed-db-service";
import { ChangelogLogic } from "./changelog-logic";
import { calculateProjectProgress } from "./progress-calculation-logic";
import { EpicLogic } from "./epic-logic";
import { generateUUID } from "./id-generation-logic";

// Helper function to get current ISO 8601 timestamp
const getCurrentTimestamp = () => new Date().toISOString();

export const ProjectLogic = (
  indexedDbService,
  changelogLogic,
  progressCalculationLogic,
  epicLogic,
  idGenerationLogic
) => {
  const projectsStoreName = "projects";

  const createProject = async (data) => {
    const timestamp = getCurrentTimestamp();
    const id = idGenerationLogic.generateUUID();

    const newProject = ProjectEntity({
      ...data,
      id,
      status: ProjectStatus.PLANNING,
      progress: 0,
      createdAt: timestamp,
      updatedAt: timestamp,
    });

    await indexedDbService.addEntity(projectsStoreName, newProject);

    await changelogLogic.recordChange(
      ChangelogEntityType.PROJECT,
      newProject.id,
      newProject.name,
      "entity_status",
      "CREATED",
      ProjectStatus.PLANNING
    );

    return newProject;
  };

  const getProject = async (id) => {
    const project = await indexedDbService.getEntity(projectsStoreName, id);

    if (project) {
      const epics = await epicLogic.getEpicsByProject(project.id);
      const calculatedProgress = progressCalculationLogic.calculateProjectProgress(epics);
      return { ...project, progress: calculatedProgress };
    }

    return undefined;
  };

  const getAllProjects = async () => {
    const projects = await indexedDbService.getEntities(projectsStoreName);
    const enrichedProjects = await Promise.all(
      projects.map(async (project) => {
        const epics = await epicLogic.getEpicsByProject(project.id);
        const calculatedProgress = progressCalculationLogic.calculateProjectProgress(epics);
        return { ...project, progress: calculatedProgress };
      })
    );
    return enrichedProjects;
  };

  const updateProject = async (id, data) => {
    const timestamp = getCurrentTimestamp();
    const originalProject = await indexedDbService.getEntity(projectsStoreName, id);

    if (!originalProject) {
      throw new Error(`Project with ID ${id} not found.`);
    }

    const updatedProject = {
      ...originalProject,
      ...data,
      updatedAt: timestamp,
    };

    for (const field in data) {
      if (Object.prototype.hasOwnProperty.call(data, field)) {
        const oldValue = String(originalProject[field]);
        const newValue = String(data[field]);

        if (oldValue !== newValue) {
          await changelogLogic.recordChange(
            ChangelogEntityType.PROJECT,
            id,
            originalProject.name,
            field,
            oldValue,
            newValue
          );
        }
      }
    }

    await indexedDbService.updateEntity(projectsStoreName, id, updatedProject);

    // Recalculate progress after update
    const epics = await epicLogic.getEpicsByProject(updatedProject.id);
    const calculatedProgress = progressCalculationLogic.calculateProjectProgress(epics);
    updatedProject.progress = calculatedProgress;

    return updatedProject;
  };

  const deleteProject = async (id) => {
    const projectToDelete = await indexedDbService.getEntity(projectsStoreName, id);

    if (!projectToDelete) {
      return; // Resolve without action if project not found
    }

    const projectName = projectToDelete.name;

    const epics = await epicLogic.getEpicsByProject(id);
    for (const epic of epics) {
      await epicLogic.deleteEpic(epic.id); // This also handles story deletions and changelog for epics/stories
    }

    await changelogLogic.recordDeletion(
      ChangelogEntityType.PROJECT,
      id,
      projectName
    );

    await indexedDbService.deleteEntity(projectsStoreName, id);
  };

  return {
    createProject,
    getProject,
    getAllProjects,
    updateProject,
    deleteProject,
  };
};